<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\{BelongsTo}; class GameKey extends Model {protected $fillable=['product_id','key','status','order_id','sold_at'];protected function casts():array{return ['key'=>'encrypted','sold_at'=>'datetime'];}public function product():BelongsTo{return $this->belongsTo(Product::class);}public function order():BelongsTo{return $this->belongsTo(Order::class);}}
